{
  "fact_1": {
    "topic": "课程开场兑现承诺与机器视角",
    "claim": "讲师在课前兑现了承诺，有人会在课结束前赢得一副Google Cardboard虚拟现实眼镜；讲师随后让听众把自己当作机器，除了听众告知的内容外一无所知，因此需要命令式知识来指导如何完成抽奖。",
    "evidence": [2, 3, 4, 5, 6, 7, 8, 10, 11, 12, 14, 15, 20, 21, 22, 23, 24],
    "attribution": "source",
    "importance": "support"
  },
  "fact_2": {
    "topic": "命令式知识的定义",
    "claim": "命令式知识是配方、操作方法或步骤序列；如果机器遵循这些步骤，理论上应能得出结论。",
    "evidence": [25, 26, 27, 31, 32, 37, 38, 39],
    "attribution": "source",
    "importance": "core"
  },
  "fact_3": {
    "topic": "用Python随机抽选课堂参与者",
    "claim": "讲师以机器方式遵循步骤，打开本课程使用的Anaconda IDE，用Python的random.randint在16到272之间随机选号，以避免人为偏好（例如偏爱数字8），并在响应者名单中找到对应的人。",
    "evidence": [44, 49, 50, 58, 59, 60, 61, 62, 69, 70, 71, 72, 73, 74, 80, 81, 82, 96, 97, 98, 99, 100, 101, 102, 105, 106, 110, 114, 115, 116, 117, 118, 119],
    "attribution": "source",
    "importance": "support"
  },
  "fact_4": {
    "topic": "鼓励日常使用Python",
    "claim": "讲师建议尽可能使用Python，因为这样能获得练习。",
    "evidence": [120, 121, 122, 123],
    "attribution": "source",
    "importance": "support"
  },
  "fact_5": {
    "topic": "声明式知识与命令式知识的数值示例对比",
    "claim": "声明式知识的例子是：数x的平方根是y，使得y乘以y等于x；这是一个事实陈述，但计算机不知道如何处理它，而计算机知道如何遵循配方。",
    "evidence": [128, 129, 130, 131, 132, 133, 134, 135, 136, 137, 138, 139, 140, 141, 142, 143, 144, 145],
    "attribution": "source",
    "importance": "core"
  },
  "fact_6": {
    "topic": "求平方根的算法步骤",
    "claim": "求数x平方根的已知算法：从猜测g开始（例如x=16时g=3），计算g*g；若g*g足够接近x则停止并称g为答案；否则通过平均g和x/g得到新猜测，并用新猜测重复整个过程，直到决定足够接近。",
    "evidence": [146, 147, 148, 149, 150, 151, 152, 153, 154, 155, 156, 157, 158, 159, 160, 161, 162, 163, 164, 165, 166, 167, 168, 169, 170, 171, 172, 173, 174, 175, 176, 177, 178, 179, 180, 181, 182, 183, 184, 185, 186, 187],
    "attribution": "source",
    "importance": "core"
  },
  "fact_7": {
    "topic": "配方的三个组成部分",
    "claim": "配方有三个部分：简单的步骤序列（该例中有四步）、控制流（包括做出决定和重复步骤）、以及停止的方式；在求平方根的例子中，停止方式是决定足够接近，接近程度可以是0.01、0.001等由人选择的值。",
    "evidence": [194, 195, 196, 197, 198, 199, 200, 201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219, 220, 221, 222, 223, 224],
    "attribution": "source",
    "importance": "core"
  },
  "fact_8": {
    "topic": "算法与课程目标",
    "claim": "在计算机科学术语中，这种配方称为算法；本课程将学习算法，并希望将配方捕获到计算机中，计算机是一种机械过程。",
    "evidence": [225, 226, 227, 228, 229, 230, 231, 232, 233, 234, 235],
    "attribution": "source",
    "importance": "core"
  },
  "fact_9": {
    "topic": "固定程序计算机",
    "claim": "历史上最初有固定程序计算机，例如早期计算器，只能做加法、减法、乘法、除法；不能绘图、上网或发邮件，只能做这一件事；若要执行另一项任务，必须制造另一台固定程序计算机。",
    "evidence": [236, 237, 238, 239, 240, 241, 242, 243, 244, 245, 246, 247, 248, 249, 250, 251, 252, 253, 254, 255, 256, 257, 258, 259, 260, 261, 262, 263, 264, 265, 266, 267],
    "attribution": "source",
    "importance": "support"
  },
  "fact_10": {
    "topic": "存储程序计算机",
    "claim": "存储程序计算机可以存储指令序列并执行该序列，也可以更改指令序列并执行不同的序列，从而在同一台机器上完成不同任务；这就是如今我们所知的计算机。",
    "evidence": [268, 269, 270, 271, 272, 273, 274, 275, 276, 277, 278, 279, 280, 281, 282],
    "attribution": "source",
    "importance": "core"
  },
  "fact_11": {
    "topic": "基本机器架构的组成部分",
    "claim": "每台计算机核心的基本机器架构包含四个主要部分：内存、输入输出、ALU（执行加法、减法等原始操作）以及控制单元；内存包含数据和指令序列。",
    "evidence": [288, 289, 290, 291, 292, 293, 294, 295, 296, 297, 298, 299, 300, 301, 302, 303, 304, 305, 306, 307, 308, 309, 310, 311],
    "attribution": "source",
    "importance": "core"
  },
  "fact_12": {
    "topic": "控制单元与程序计数器的执行流程",
    "claim": "控制单元包含一个程序计数器；加载指令序列时，程序计数器从第一条指令开始，取出指令并发送给ALU；ALU可能从内存获取数据、执行操作并将数据存回内存；完成后程序计数器增加1，转到下一条指令，线性逐条执行；某条指令可能进行测试，例如判断某个值是否大于、等于或等于另一个值。",
    "evidence": [312, 313, 314, 315, 316, 317, 318, 319, 320, 321, 322, 323, 324, 325, 326, 327, 328, 329, 330, 331, 332, 333, 334, 335, 336, 337, 338, 339, 340, 341, 342, 343, 344, 345, 346, 347, 348],
    "attribution": "source",
    "importance": "core"
  }
}
